DZ · Kirish tayyor.kod:
var inp = $("DZ · VIZUAL_TIZIM").first().json;
var kar = $("DZ · Karusel jadvali").all().map(function(i){return i.json;});
var sj = $("DZ · s_jadval").all().map(function(i){return i.json;});
var kod = String(inp.karusel_kod||"");
var mavzu = String(inp.mavzu_kod||"");
var slaydlar = kar.filter(function(r){ var k=String(r.karusel||""); return (kod && k.indexOf(kod+" ")===0) || (!kod && k.indexOf(" "+mavzu+" ")>=0); })
  .sort(function(a,b){ return Number(a.slayd)-Number(b.slayd); })
  .map(function(r){ return { n:Number(r.slayd), sarlavha:r.sarlavha||"", tana:r.tana||"", vizual:r.vizual||"" }; });
var faktlar = sj.filter(function(r){ return String(r.mavzu_kodlar||"").split(",").map(function(s){return s.trim();}).indexOf(mavzu)>=0 && String(r.faol)!=="false"; })
  .map(function(r){ return { s_id:r.s_id, ekran:r.matn_tr, manba:r.manba, manba_toliq:r.manba_toliq, rang:r.rang, meta_tiktok:r.meta_tiktok, daraja:r.daraja }; });
var xato = [];
if(!slaydlar.length) xato.push("karusel jadvalida bu kod/mavzu uchun slayd yoq");
if(!faktlar.length) xato.push("s_jadval'da bu mavzu uchun fakt yoq");
return [{ json: Object.assign({}, inp, { slaydlar:slaydlar, faktlar:faktlar, kirish_xato:xato }) }];

